<template><ion-page><ion-content><main class="studio"><header><button @click="router.back()">Back</button><p>MANUSH-E / SCENARIO STUDIO</p></header><section v-if="!active"><p>GUIDED PRACTICE</p><h1>Practise the hard conversations.</h1><article v-for="scenario in scenarios" :key="scenario.id" @click="active=scenario"><span>{{ scenario.icon }}</span><div><h2>{{ scenario.title }}</h2><p>{{ scenario.context }}</p><small>{{ scenario.source }}</small></div></article></section><section v-else class="practice"><p>{{ active.title }}</p><h1>{{ active.childVoice }}</h1><textarea v-model="response" placeholder="Write what you would say..."></textarea><button @click="submitted=true">Try your response</button><div v-if="submitted" class="coach"><strong>Coach notes</strong><p>{{ active.coach }}</p><small>Source: {{ active.source }}</small></div></section></main></ion-content></ion-page></template>
<script setup lang="ts">import{ref}from'vue';import{IonContent,IonPage}from'@ionic/vue';import{useRouter}from'vue-router';const router=useRouter(),active=ref<any>(null),response=ref(''),submitted=ref(false);const scenarios=[{id:'conflict',icon:'~',title:'After-school conflict',context:'A child refuses to talk after a difficult day.',childVoice:'“You will not understand. Just leave me alone.”',coach:'Start by lowering the temperature: name what you notice, offer space, and leave a clear invitation to return. Avoid solving the problem before the child feels heard.',source:'UNICEF: Supporting teens during stressful times'},{id:'classroom',icon:'*',title:'Classroom shutdown',context:'A student has stopped participating after making a mistake.',childVoice:'“I am not doing this. Everyone thinks I am stupid.”',coach:'Respond privately, acknowledge the moment without judgment, and offer one small next step. Restore belonging before returning to the task.',source:'UNICEF: Teacher-student activities for wellbeing'},{id:'screen',icon:'o',title:'Screen-time argument',context:'A child becomes angry when asked to stop playing.',childVoice:'“You always take everything away from me!”',coach:'Keep the boundary clear and calm. Name the disappointment, avoid a power struggle, and agree on the next predictable transition together.',source:'WHO parenting interventions guideline'}];</script>
<style scoped>.studio{background:#f5f0e7;color:#18342f;min-height:100%;padding:24px max(22px,calc((100vw - 800px)/2))}header{display:flex;justify-content:space-between}button{background:#1e6650;border:0;border-radius:100px;color:white;padding:12px 17px}h1,h2{font-family:Georgia,serif;font-weight:400}h1{font-size:clamp(2.8rem,10vw,4.8rem)}article,.practice{background:white;border-radius:20px;display:flex;gap:15px;margin:14px 0;padding:18px}article span{font:3rem Georgia,serif}article h2{margin:0}small{color:#62736b}.practice{display:block}.practice textarea{border:1px solid #cbd8cc;border-radius:15px;box-sizing:border-box;margin:18px 0;min-height:130px;padding:14px;width:100%}.coach{background:#e0ecdf;border-radius:14px;margin-top:20px;padding:16px}</style>
